public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,4>CodeRanges{{{0x5ee,0x638},{0x1fac,0x2036},{0x3c10,0x3c48},{0x401c,0x403c}}};bool active()const{return depth_||services_.active()||keys_.active();}void reset(){depth_=0;services_.reset();keys_.reset();steps_=0;}uint64_t steps()const{return steps_;}unsigned requestedChild()const{return depth_?jobs_[depth_-1].child:0;}static bool candidate(unsigned at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
